import { PageHeader } from '@gntik-ai/blocks';
import { Alert, Checkbox, ClickableCard, Grid, GridItem, Page, Progress, Section, Stack, type BreadcrumbItem } from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { docLinks, setupInitialDone, setupTasks, startBreadcrumbs, type DocLink, type SetupTask } from './data';

export interface GettingStartedProps {
  title: string;
  description: string;
  breadcrumbs: BreadcrumbItem[];
  tasks: readonly SetupTask[];
  /** Ids of the tasks already done (initial state). */
  defaultDone: readonly string[];
  /** Fires with every change of the done list. */
  onDoneChange: (done: string[]) => void;
  docs: readonly DocLink[];
  onDocOpen: (id: string) => void;
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Getting started: a setup checklist with progress, and cards linking to the docs. */
export default function GettingStartedPage({
  title = 'Get started',
  description = 'A few steps to set up your workspace. You can come back to this page at any time.',
  breadcrumbs = startBreadcrumbs,
  tasks = setupTasks,
  defaultDone = setupInitialDone,
  onDoneChange,
  docs = docLinks,
  onDocOpen,
  shell,
}: Partial<GettingStartedProps>) {
  const [done, setDone] = useState<string[]>(() => [...defaultDone]);
  const count = tasks.filter((t) => done.includes(t.id)).length;
  const percent = tasks.length ? Math.round((count / tasks.length) * 100) : 0;

  const toggle = (id: string, checked: boolean) => {
    const next = checked ? [...done.filter((d) => d !== id), id] : done.filter((d) => d !== id);
    setDone(next);
    onDoneChange?.(next);
  };

  return (
    <ConsoleShell currentHref="/overview" breadcrumbs={breadcrumbs} {...shell}>
      <Page header={<PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} actions={[]} tabs={null} />}>
        <Grid cols={{ base: 1, lg: 3 }} gap={6} align="start">
          <GridItem span={{ base: 1, lg: 2 }}>
            <Section variant="card" padding="lg" divided title="Setup checklist" description={`${count} of ${tasks.length} steps complete`}>
              <Progress value={percent} label="Setup progress" showValue tone={count === tasks.length ? 'success' : undefined} />
              {count === tasks.length && (
                <Alert tone="success" title="You’re all set" description="Your workspace is ready. Explore the docs to go further." />
              )}
              <Stack gap={4}>
                {tasks.map((task) => (
                  <Checkbox
                    key={task.id}
                    label={task.title}
                    description={task.description}
                    checked={done.includes(task.id)}
                    onCheckedChange={(checked) => toggle(task.id, checked)}
                  />
                ))}
              </Stack>
            </Section>
          </GridItem>
          <Section title="Learn more" description="Guides and reference for every step.">
            <Stack gap={3}>
              {docs.map((doc) => {
                const Icon = doc.icon;
                return (
                  <ClickableCard
                    key={doc.id}
                    title={doc.title}
                    description={doc.description}
                    href={doc.href}
                    icon={<Icon aria-hidden />}
                    onClick={() => onDocOpen?.(doc.id)}
                  />
                );
              })}
            </Stack>
          </Section>
        </Grid>
      </Page>
    </ConsoleShell>
  );
}

import { BookOpen, Code2, LifeBuoy, PlayCircle, type LucideIcon } from '@gntik-ai/icons';
import type { BreadcrumbItem } from '@gntik-ai/ui';

export interface SetupTask {
  id: string;
  title: string;
  description: string;
}

export interface DocLink {
  id: string;
  title: string;
  description: string;
  href: string;
  icon: LucideIcon;
}

export const startBreadcrumbs: BreadcrumbItem[] = [{ label: 'Overview', href: '/overview' }, { label: 'Get started' }];

export const setupTasks: SetupTask[] = [
  { id: 'workspace', title: 'Create your workspace', description: 'Name it and pick the region where your data lives.' },
  { id: 'project', title: 'Create a project', description: 'Import a repository or start from a template.' },
  { id: 'deploy', title: 'Ship your first deployment', description: 'Push to the main branch or deploy from the console.' },
  { id: 'invite', title: 'Invite your team', description: 'Add teammates and choose what each of them can do.' },
  { id: 'billing', title: 'Add a payment method', description: 'Needed before you go over the free plan limits.' },
];

export const setupInitialDone: string[] = ['workspace', 'project'];

export const docLinks: DocLink[] = [
  { id: 'quickstart', title: 'Quickstart', description: 'Deploy a sample service in five minutes.', href: '#quickstart', icon: PlayCircle },
  { id: 'concepts', title: 'Core concepts', description: 'Workspaces, projects, environments and deployments.', href: '#concepts', icon: BookOpen },
  { id: 'api', title: 'API reference', description: 'Automate everything you can do in the console.', href: '#api', icon: Code2 },
  { id: 'support', title: 'Get help', description: 'Guides, community forum and support.', href: '#support', icon: LifeBuoy },
];

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
